import{_ as a,o as r,c as t,aS as n}from"./chunks/framework.DsJaIkSj.js";const p=JSON.parse('{"title":"ADR：当前 Element Plus implementation 与未来 renderer seam","description":"","frontmatter":{},"headers":[],"relativePath":"adr/2026-08-06-current-element-implementation-and-future-renderer-seam.md","filePath":"adr/2026-08-06-current-element-implementation-and-future-renderer-seam.md","lastUpdated":null}'),l={name:"adr/2026-08-06-current-element-implementation-and-future-renderer-seam.md"};function i(o,e,m,d,s,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-当前-element-plus-implementation-与未来-renderer-seam" tabindex="-1">ADR：当前 Element Plus implementation 与未来 renderer seam <a class="header-anchor" href="#adr-当前-element-plus-implementation-与未来-renderer-seam" aria-label="Permalink to &quot;ADR：当前 Element Plus implementation 与未来 renderer seam&quot;">​</a></h1><p>日期：2026-08-06 状态：Accepted</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p><code>qy-components</code> 当前是 Vue 3 + Element Plus 主 implementation。公开 UI 声明仍存在 Element Plus 类型泄漏，且实现中仍直接使用 Element Plus；因此不能将仓库描述为已支持 Naive UI、React 或无成本替换 renderer。</p><p>业务与消费者需要稳定、可演进的面，同时不应被当前实现细节锁定。来自 <code>qy-permission</code> 的 2026-06-27 ADR 是同一方向的来源证据，但本 ADR 是本仓库的内部权威。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><ol><li>当前只维护 Element Plus implementation。稳定面是 Qy interface、Qy schema、Qy tokens 和宿主 runtime。</li><li>新增公共 interface 由 Qy 定义；不得新增厂商类型、实例、私有 DOM/VNode/Node/Store、私有事件或 <code>--el-*</code> 作为业务必须依赖的契约。既有泄漏按模块渐进治理。</li><li>简单模块可直接 import 当前 implementation，不机械拆出物理 renderer 或 adapter 目录。</li><li>复杂受控状态、浮层/teleport/focus、递归节点、厂商回调对象、底层默认行为与 Qy 契约不同，是需要明确内部 adapter seam 的风险信号。</li><li>只有出现第二个真实 renderer/消费者需求后，才通过新的 ADR 决定是否分包、构建入口、注册方式或其他交付形态。</li></ol><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><ul><li>不新增运行时 <code>framework</code> 参数、provider、renderer 注册器、双实现或多构建入口。</li><li>QyContainer 等“Qy 默认行为不同于底层组件”的场景可作为按需隔离的例子，不构成所有组件复制同一目录模板的要求。</li><li>后续消费者、迁移文档与 PRP 只能引用本 ADR 及 Qy 公共 interface，不得各自定义 renderer 规则。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./../contracts/ui-public-interface">UI 公共 interface</a></li><li><a href="./../contracts/package-exports-and-runtime">包 exports 与宿主 runtime</a></li><li><a href="./../01-architecture">架构</a></li></ul>',11)])])}const h=a(l,[["render",i]]);export{p as __pageData,h as default};
